var GPT_Client = class {
  constructor(options, api_key) {
    this.options = options;
    this.api_key = api_key;
    this.history = [];
    this.is_buffering = false;
  }
  buffer(enable) {
    this.is_buffering = enable;
    return this;
  }
  set_agent_message(message) {
    this.history.push({
      role: "assistant",
      content: message
    });
  }
  set_system_message(message) {
    const system_message = this.history.find((message2) => message2.role === "system");
    if (system_message) {
      system_message.content = message;
    } else {
      this.history.unshift({
        role: "system",
        content: message
      });
    }
  }
  async send(messages, additional_config) {
    if (this.is_buffering) {
      return {
        type: "message",
        data: ""
      };
    }
    const response = await this.completions_request(messages, additional_config);
    const choice = response.choices[0];
    if (!choice) {
      throw new Error("No response from GPT");
    }
    this.history.push(choice.message);
    if (choice.message.function_call) {
      return {
        type: "function_call",
        data: choice.message.function_call
      };
    }
    if (choice.message.content) {
      return {
        type: "message",
        data: choice.message.content
      };
    }
    throw new Error("Received a response, but without a function call or content.");
  }
  async chat(message, additional_config = {}) {
    this.history.push({
      role: "user",
      content: message
    });
    return await this.send(this.history, additional_config);
  }
  async completions_request(messages, additional_config) {
    const url = "https://api.openai.com/v1/chat/completions";
    const headers = {
      "Content-Type": "application/json",
      "Authorization": `Bearer ${this.api_key || process.env.OPENAI_API_KEY}`
    };
    const body = {
      ...this.options,
      messages,
      ...additional_config
    };
    try {
      const res = await pRetry(
        () => fetch(url, {
          method: "POST",
          headers,
          keepalive: false,
          body: JSON.stringify(body)
        }),
        {
          retries: 10,
          onFailedAttempt: (error) => {
            client.retry(`${error.attemptNumber}/10 Failed to get a response from OpenAI. `).debug(error);
          }
        }
      );
      client.info("Body:", body);
      if (!res.ok) {
        const message = await res.text();
        client.problem("OpenAI Response:", message);
        switch (res.status) {
          case 429:
            throw new Error("Error 429: Too many requests. Please slow down your request rate.");
          case 503:
          case 500:
            throw new Error("Error 500: Server error. Please try again later.");
          case 400:
            throw {
              code: 400,
              ...JSON.parse(message)
            };
          default:
            throw new Error(`Error ${res.status}: ${res.statusText}`);
        }
      }
      const data = await res.json();
      client.debug("GPT Response:", data);
      return data;
    } catch (err) {
      console.error("Failed to parse the response from OpenAI", err);
      throw err;
    }
  }
};
